"""Regenerate the exact backup registry and v13 atomic restore program after schema changes.
Run from the repository root using Python 3. No production database is accessed.
"""
import json,pathlib,sqlite3
con=sqlite3.connect(':memory:')
for p in sorted(pathlib.Path('migrations').glob('*.sql')):con.executescript(p.read_text())
order=['family_members','accounts','categories','settings','investments','transactions','sms_messages','category_rules','ai_category_usage','ai_category_jobs','ai_category_audits','investment_activity','payroll_records','payroll_contributions','nps_statements','nps_credit_matches','investment_payments','investment_valuations','bill_plans','bill_periods','transaction_splits','import_batches','import_rows','saved_report_views','statement_imports','statement_import_items','statement_ai_attempts']
scope={t:'workspace_id = ?' for t in order}
for t in ['investment_activity','investment_payments','investment_valuations','nps_credit_matches']:scope[t]='investment_id IN (SELECT id FROM investments WHERE workspace_id = ?)'
scope['payroll_contributions']='payroll_id IN (SELECT id FROM payroll_records WHERE workspace_id = ?)'
scope['bill_periods']='plan_id IN (SELECT id FROM bill_plans WHERE workspace_id = ?)'
scope['transaction_splits']='transaction_id IN (SELECT id FROM transactions WHERE workspace_id = ?)'
scope['import_rows']='batch_id IN (SELECT id FROM import_batches WHERE workspace_id = ?)'
registry=[]
for t in order:
 registry.append({'name':t,'scope':scope[t],'columns':[{'name':r[1],'type':r[2],'required':bool(r[3]),'pk':bool(r[5])} for r in con.execute('PRAGMA table_info('+t+')')],'references':[{'column':r[3],'table':r[2],'target':r[4]}for r in con.execute('PRAGMA foreign_key_list('+t+')')]})
pathlib.Path('worker/lib/backup-registry.ts').write_text('// Generated by scripts/generate-backup-contract.py; verified against live migration schema in tests.\nexport const BACKUP_TABLES = '+json.dumps(registry,indent=2)+' as const\n')
p=pathlib.Path('migrations/0013_ai_statement_imports.sql');s=p.read_text();marker='-- Restore contract v13'
if marker in s:s=s[:s.index(marker)]
lines=[marker+' includes AI statements and excludes temporary request controls.','DROP TRIGGER recovery_apply;','CREATE TRIGGER recovery_apply AFTER INSERT ON recovery_payloads BEGIN',' DELETE FROM statement_commit_context WHERE workspace_id=NEW.workspace_id;',' DELETE FROM import_commit_guards WHERE workspace_id=NEW.workspace_id;',' DELETE FROM workflow_claims WHERE workspace_id=NEW.workspace_id;']
for t in reversed(registry):lines.append(' DELETE FROM '+t['name']+' WHERE '+t['scope'].replace('?','NEW.workspace_id')+';')
for t in registry:
 names=[c['name'] for c in t['columns']];conflict=''
 if t['name']=='payroll_contributions':conflict=' ON CONFLICT(id) DO UPDATE SET '+','.join(c+'=excluded.'+c for c in names if c!='id')
 lines.append(' INSERT INTO '+t['name']+'('+','.join(names)+') SELECT '+','.join("json_extract(value,'$."+c+"')" for c in names)+" FROM json_each(NEW.payload_json,'$.tables."+t['name']+"') WHERE 1"+conflict+';')
lines.append('END;')
p.write_text(s+'\n'+'\n'.join(lines)+'\n')
